-- Diagnostic wrappers generated by tools/validation/instrument_lua.py; edit bodies normally.
local APRTrace = APRInstrumentation and APRInstrumentation.Wrap or function(_, fn) return fn end
local APRYield = APRInstrumentation and APRInstrumentation.Yield or coroutine.yield
local APRResume = APRInstrumentation and APRInstrumentation.Resume or coroutine.resume
local APRPCall = APRInstrumentation and APRInstrumentation.PCall or pcall
-- Selects the live waypoint target and supplies its route text to the library.

local Adapter = APR.NavigationAdapter
local Shared = APR.NavigationAdapter._helpers
local Call = Shared.Call
local Number = Shared.Number
local Text = Shared.Text
local environment = Shared.environment

function Adapter:GetWaypointContext(step, index)
    local context = APR.CaptureStepContext and APR:CaptureStepContext() or {}
    return table.concat({
        tostring(context.player),
        tostring(context.route or APR.ActiveRoute),
        tostring(index or context.index),
        tostring(context.revision),
        tostring(context.definition),
        tostring(step),
    }, "\031")
end--[[APR_DIAG]]; Adapter.GetWaypointContext = APRTrace("APR-Core/features/navigation/adapter/NavigationAdapterWaypoints.lua:15:Adapter:GetWaypointContext#1", Adapter.GetWaypointContext)--[[/APR_DIAG]]

function Adapter:IsWaypointCompleted(step)
    if step.ZoneStepTrigger or not C_QuestLog or not C_QuestLog.IsQuestFlaggedCompleted then return false end
    if Call(C_QuestLog.IsQuestFlaggedCompleted, step.Waypoint) == true then return true end
    for _, id in ipairs(step.WaypointDB or {}) do
        if Call(C_QuestLog.IsQuestFlaggedCompleted, id) == true then return true end
    end
    return false
end--[[APR_DIAG]]; Adapter.IsWaypointCompleted = APRTrace("APR-Core/features/navigation/adapter/NavigationAdapterWaypoints.lua:27:Adapter:IsWaypointCompleted#2", Adapter.IsWaypointCompleted)--[[/APR_DIAG]]

function Adapter:GetWaypointText(step, point, token)
    local title = point and Text(point.label or point.instruction)
    if not title then
        if not self.waypointSummary or self.waypointSummary.token ~= token then
            self.waypointSummary = {
                token = token,
                text = APR.CheckWaypointText and APR:CheckWaypointText(),
            }
        end
        title = Text(self.waypointSummary.text)
    end
    local lines, seen, keys = {}, {}, {}
    local function Add(raw)
        if not APR.ResolveStepTextList then return end
        for _, line in ipairs(APR:ResolveStepTextList(raw)) do
            if Text(line.text) and line.text ~= title and not seen[line.text] then
                seen[line.text], lines[#lines + 1] = true, line.text
            end
        end
    end--[[APR_DIAG]]; Add = APRTrace("APR-Core/features/navigation/adapter/NavigationAdapterWaypoints.lua:48:Add#4", Add)--[[/APR_DIAG]]
    Add(step.Note)
    for key in pairs(step) do
        if type(key) == "string" and key:match("^ExtraLineText%d*$") then keys[#keys + 1] = key end
    end
    table.sort(keys)
    for _, key in ipairs(keys) do
        Add(step[key])
    end
    return title or "APR", #lines > 0 and table.concat(lines, "\n") or nil
end--[[APR_DIAG]]; Adapter.GetWaypointText = APRTrace("APR-Core/features/navigation/adapter/NavigationAdapterWaypoints.lua:36:Adapter:GetWaypointText#3", Adapter.GetWaypointText)--[[/APR_DIAG]]

function environment.getWaypointTarget(finalDestination)
    Adapter.waypointTargetAvailable = nil
    local profile = APR.settings and APR.settings.profile
    if
        not profile
        or not profile.enableAddon
        or (not APR.ActiveRoute and not (APR.Services and APR.Services.active))
    then
        return nil, { guideMode = "blocked" }
    end
    local step, index
    local service = APR.Services and APR.Services:GetStep()
    if service then
        step, index = service, 1
    elseif APR.GetCurrentStep then
        step, index = APR:GetCurrentStep()
    elseif APR.PeekCurrentStep then
        step = APR:PeekCurrentStep()
    end
    local options = { guideMode = "blocked", context = Adapter:GetWaypointContext(step, index) }
    if
        not profile
        or not profile.enableAddon
        or (not APR.ActiveRoute and not service)
        or Call(UnitIsDeadOrGhost, "player") == true
        or not step
    then
        return nil, options
    end

    local preview, navigation, point, transient = APR.navigationPreview, APR.navigation
    local destination
    if finalDestination and preview and not step.NoArrow then
        local context = navigation
            and (
                (navigation.state ~= "ready" and navigation.state ~= "instance" and navigation._routedStepContext)
                or navigation.waypointDestinationContext
            )
        if service then
            destination = service.target
        elseif context and APR.IsStepContextCurrent and APR:IsStepContextCurrent(context) then
            destination = navigation.destination
        end
    end
    if destination then
        if step.Waypoint and Adapter:IsWaypointCompleted(step) then return nil, options end
        point = preview:Point({
            Coord = { x = destination.y, y = destination.x },
            uiMapID = destination.uiMapID,
            instanceID = destination.instanceID,
            accessKey = destination.accessKey,
            floor = destination.floor,
            label = service and APR.Services:GetLabel(),
        })
    elseif APR.stepUpdateRunning or APR.stepUpdatePending then
        return nil, options
    elseif navigation and navigation.retainedArrow then
        point, transient = navigation:GetRetainedArrow(), true
    elseif navigation and navigation:IsNavigating() then
        if
            navigation.context
            and (
                (service and not APR.Services:IsContextCurrent(navigation.context))
                or (not service and APR.IsStepContextCurrent and not APR:IsStepContextCurrent(navigation.context))
            )
        then
            return nil, options
        end
        point, transient = navigation:GetActiveStep(), true
    elseif navigation and navigation.state ~= "ready" then
        return nil, options
    end
    -- Ordinary quest objectives retain AzerothWaypoint's existing extractor,
    -- metadata and icon selection. APR only supplies authored positional goals.
    if not destination and not transient and not step.Waypoint then
        options.guideMode = "fallback"
        return nil, options
    end
    options.guideMode = "override"
    if not preview then return nil, options end
    if transient then
        if not point or point.displayAction or (point.sourceFree and point.action) then return nil, options end
    elseif not destination then
        if step.NoArrow or not APR.IsInRouteZone or Adapter:IsWaypointCompleted(step) then return nil, options end
        local _, routeMap = APR:GetCurrentRouteMapIDsAndName()
        local hint = APR:GetPlayerParentMapID()
        local coord, zone = APR:GetStepCoord(step, routeMap, hint)
        local mapID = zone
            or (APR.GetStepZoneForPlayer and APR:GetStepZoneForPlayer(step, routeMap, hint))
            or (type(step.Zone) == "number" and step.Zone)
            or routeMap
        point = preview:Point({ Coord = coord, uiMapID = mapID, instanceID = step.instanceID })
    end
    if not point or not point.Coord then return nil, options end
    local coord = point.Coord
    if not Number(coord.x) or not Number(coord.y) then return nil, options end
    local mapID = coord.mapID or point.uiMapID
    if not Number(mapID) or mapID <= 0 then return nil, options end
    local instanceID = point.instanceID or coord.instanceID or preview:GetMapInstance(mapID)
    local playerY, playerX
    if not destination then
        local _, playerInstance
        playerY, playerX, _, playerInstance = Call(UnitPosition, "player")
        if not Number(playerInstance) or (instanceID ~= nil and instanceID ~= playerInstance) then
            return nil, options
        end
    end
    local x, y = preview:ProjectPoint(point, mapID)
    if not Number(x) or not Number(y) or x < 0 or x > 1 or y < 0 or y > 1 then return nil, options end
    local token = table.concat({
        options.context,
        transient and tostring(point.id or point) or "step",
        tostring(instanceID),
        tostring(mapID),
        tostring(x),
        tostring(y),
    }, "\031")
    if Adapter.waypointArrivedToken == token then return nil, options end
    -- Retiring a nearby marker never advances the guide or changes route state.
    if
        not transient
        and not destination
        and Number(step.Range)
        and step.Range > 0
        and Number(playerX)
        and Number(playerY)
    then
        local playerMap = C_Map and Call(C_Map.GetBestMapForUnit, "player")
        local projected = preview:ProjectPoint(point, playerMap)
        if projected and (coord.x - playerX) ^ 2 + (coord.y - playerY) ^ 2 < step.Range ^ 2 then
            Adapter.waypointArrivedToken = token
            return nil, options
        end
    end
    Adapter.waypointTargetAvailable = true
    local title, subtext = Adapter:GetWaypointText(step, point, token)
    options.name, options.token = title .. (subtext and "\n" .. subtext or ""), token
    return {
        space = "map",
        uiMapID = mapID,
        mapID = mapID,
        x = x,
        y = y,
        title = title,
        subtext = subtext,
        token = token,
        transient = transient,
        finalDestination = destination and true,
        source = "apr.step#" .. tostring(index) .. (transient and ":" .. tostring(point.id or "navigation") or ""),
        kind = "guide_goal",
        guideProvider = "apr",
        worldPosition = { instanceID = instanceID, x = coord.y, y = coord.x },
    },
        options
end--[[APR_DIAG]]; environment.getWaypointTarget = APRTrace("APR-Core/features/navigation/adapter/NavigationAdapterWaypoints.lua:67:environment.getWaypointTarget#5", environment.getWaypointTarget)--[[/APR_DIAG]]
